head.script:
scwin.screenId = "jldstf07301";

///////// 1. 변수 및 선언 영역 /////////

scwin.panel_debug = $c.util.getComponent('panel_debug');

scwin.vScrenID = "ULDSTF07301.gfm";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_SetCode();
        scwin.fn_Init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_Grid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid')) : $c.util.getComponent('dts_Grid');

scwin.pMarket = undefined; try { scwin.pMarket = /* sdd-asis-lifecycle:begin pMarket — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07301' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07301.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_Save();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.btn_Save_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.btn_Close_onclick' }); }
};

/**
 * @method
 * @name scwin.trs_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onfail = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("저장에 실패하였습니다.");
    $c.fil.alert_error(trs_Save);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("저장하였습니다.");
    scwin.parentRefresh();
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_Grid
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_Grid = async function () {
    $c.util.getComponent("dma_scriptDts_GridReq").set("SCREN_ID", "ULDSTF07301.gfm");
    $c.util.getComponent("dma_scriptDts_GridReq").set("inputMessageId", "PREPARE_CORP_STATUS");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO", unresolved: "query_param:SCREN_PROCES_TP_CD,BZ_PROCS_NO" };
    const sbmOptions = {
        id: "tx_script_dts_Grid",
        method: "post",
        action: "/konex/Prelisting.do",
        ref: "dma_scriptDts_GridReq",
        target: "dts_Grid=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Grid_onloaderror'] === 'function') ? scwin['dts_Grid_onloaderror'] : (typeof scwin['dts_Grid_onfail'] === 'function') ? scwin['dts_Grid_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Grid_onloadcompleted'] === 'function') ? scwin['dts_Grid_onloadcompleted'] : ((typeof scwin['dts_Grid_onsuccess'] === 'function') ? scwin['dts_Grid_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Grid'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07301.tx_script_dts_Grid" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.sbm_trs_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/konex/Prelisting.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07301.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.hideDebugCtrls
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.hideDebugCtrls = function () {
    /* sdd-asis-lifecycle:begin fn_HideDebugCtrls — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.showObj(scwin.panel_debug, false);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.parentRefresh
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.parentRefresh = function () {
    /* sdd-asis-lifecycle:begin fn_parentRefresh — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_Init = scwin.tx_script_dts_Grid;

scwin.fn_Save = scwin.sbm_trs_Save;
